/**
 * Calculate task start and finish times (with unlimited workers)
 */
function calculateTiming(tasks, deps, depths) {
  const starts = new Map()
  const finishes = new Map()

  function getFinish(name) {
    if (finishes.has(name)) {
      return finishes.get(name)
    }

    const depList = deps.get(name) || []
    let maxDepFinish = 0
    for (const dep of depList) {
      maxDepFinish = Math.max(maxDepFinish, getFinish(dep))
    }

    starts.set(name, maxDepFinish)
    const finish = maxDepFinish + tasks.get(name).cost
    finishes.set(name, finish)
