    return { error: 'usage: cli.js waves|explain|pack <workers>' }
  }

  const cmd = args[0]
  if (cmd === 'waves' || cmd === 'explain') {
    if (args.length !== 1) {
      return { error: 'usage: cli.js waves|explain|pack <workers>' }
    }
    return { cmd }
  } else if (cmd === 'pack') {
    if (args.length !== 2) {
      return { error: 'usage: cli.js waves|explain|pack <workers>' }
    }
    const workers = args[1]
    // Check if workers is a positive integer without leading zero
    if (!/^[1-9]\d*$/.test(workers)) {
      return { error: 'workers must be a positive integer' }
    }
    return { cmd, workers: parseInt(workers, 10) }
  } else {
    return { error: 'usage: cli.js waves|explain|pack <workers>' }
  }
}

/**
 * Validate task name
 */
function isValidTaskName(name) {
  return /^[A-Za-z0-9_.\-]+$/.test(name)
}

/**
 * Parse input graph
 */
async function parseInput() {
  const tasks = new Map()
  const deps = new Map()
  let lineNum = 0

  const rl = readline.createInterface({
    input: process.stdin,
    crlfDelay: Infinity
  })

  for await (const line of rl) {
    lineNum++
    const trimmed = line.trim()

    // Skip empty lines and comments
    if (trimmed === '' || trimmed.startsWith('#')) {
      continue
    }

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        return { error: `error: line ${lineNum}: expected task <name> <cost>` }
      }
      const [, name, costStr] = words
      if (!isValidTaskName(name)) {
        return { error: `error: line ${lineNum}: invalid task name ${name}` }
      }
      if (!/^\d+$/.test(costStr)) {
        return { error: `error: line ${lineNum}: cost must be a non-negative integer` }
      }
      const cost = parseInt(costStr, 10)
      if (tasks.has(name)) {
        return { error: `error: line ${lineNum}: task ${name} is declared twice` }
      }
      tasks.set(name, { cost, lineNum })
      if (!deps.has(name)) {
        deps.set(name, [])
      }
    } else if (directive === 'dep') {
      if (words.length < 2) {
        return { error: `error: line ${lineNum}: expected dep <name> <dependency>...` }
      }
      const [, name, ...dependencies] = words
      if (!deps.has(name)) {
        deps.set(name, [])
      }
      const uniqueDeps = [...new Set(dependencies)]
      deps.set(name, uniqueDeps)
    } else {
      return { error: `error: line ${lineNum}: unknown directive ${directive}` }
    }
  }

  return { tasks, deps }
}

/**
 * Validate that all referenced tasks exist
 */
function validateTasks(tasks, deps) {
  for (const [name, depList] of deps.entries()) {
    for (const dep of depList) {
      if (!tasks.has(dep)) {
        return { error: `error: unknown task ${dep}` }
      }
    }
  }
  return null
}

/**
 * Detect cycles using DFS
 */
function detectCycle(tasks, deps) {
  const visited = new Set()
  const recStack = new Set()
  const stack = []

  function dfs(node) {
    visited.add(node)
    recStack.add(node)
    stack.push(node)

    const depList = deps.get(node) || []
    for (const dep of depList) {
      if (recStack.has(dep)) {
        // Found cycle - find where it starts in stack
        const cycleStart = stack.indexOf(dep)
        const cycle = stack.slice(cycleStart)
        const cycleStr = [...cycle, dep].join(' -> ')
        return cycleStr
      }
      if (!visited.has(dep)) {
        const result = dfs(dep)
        if (result) return result
      }
    }

    stack.pop()
    recStack.delete(node)
    return null
  }

  // Sort tasks by name for consistent cycle detection
  const sortedNames = Array.from(tasks.keys()).sort()
  for (const name of sortedNames) {
    if (!visited.has(name)) {
      const cycle = dfs(name)
      if (cycle) return cycle
    }
  }

  return null
}

/**
 * Calculate task depths and waves
 */
function calculateDepths(tasks, deps) {
  const depths = new Map()
  const memo = new Map()

  function getDepth(name) {
    if (memo.has(name)) {
      return memo.get(name)
    }

    const depList = deps.get(name) || []
    if (depList.length === 0) {
      memo.set(name, 0)
      return 0
    }

    let maxDepth = 0
    for (const dep of depList) {
      maxDepth = Math.max(maxDepth, getDepth(dep) + 1)
    }
    memo.set(name, maxDepth)
    return maxDepth
  }

  for (const name of tasks.keys()) {
    depths.set(name, getDepth(name))
  }

  return depths
}

/**
 * Calculate task start and finish times (with unlimited workers)
 */
function calculateTiming(tasks, deps, depths) {
  const starts = new Map()
  const finishes = new Map()

  function getFinish(name) {
    if (finishes.has(name)) {
      return finishes.get(name)
    }

    const depList = deps.get(name) || []
    let maxDepFinish = 0
    for (const dep of depList) {
      maxDepFinish = Math.max(maxDepFinish, getFinish(dep))
    }

    starts.set(name, maxDepFinish)
    const finish = maxDepFinish + tasks.get(name).cost
    finishes.set(name, finish)
    return finish
  }

  for (const name of tasks.keys()) {
    getFinish(name)
  }

  return { starts, finishes }
}

/**
 * Calculate task priorities (longest chain from this task)
 */
function calculatePriorities(tasks, deps) {
  const priorities = new Map()
  const memo = new Map()

  function getPriority(name) {
    if (memo.has(name)) {
      return memo.get(name)
    }

    let maxChildPriority = 0
    for (const [taskName, depList] of deps.entries()) {
      if (depList.includes(name)) {
        maxChildPriority = Math.max(maxChildPriority, getPriority(taskName))
      }
    }

    const priority = tasks.get(name).cost + maxChildPriority
    memo.set(name, priority)
    return priority
  }

  for (const name of tasks.keys()) {
    priorities.set(name, getPriority(name))
  }

  return priorities
}

/**
 * Simulate pack scheduling
 */
function pack(tasks, deps, workers) {
  const workerFree = Array(workers).fill(0)
  const workerTasks = Array.from({ length: workers }, () => [])
  const finishes = new Map()

  // Calculate priorities
  const priorities = calculatePriorities(tasks, deps)

  // Track which tasks are done
  const done = new Set()

  let time = 0
  while (done.size < tasks.size) {
    // Find ready tasks
    const ready = []
    for (const [name, taskInfo] of tasks.entries()) {
      if (done.has(name)) continue

      const depList = deps.get(name) || []
      let allDepsReady = true
      for (const dep of depList) {
        if (!done.has(dep) || finishes.get(dep) > time) {
          allDepsReady = false
          break
        }
      }

      if (allDepsReady) {
        ready.push(name)
      }
    }

    if (ready.length === 0) {
      // No ready tasks - advance time to next worker free
      let nextTime = Infinity
      for (let i = 0; i < workers; i++) {
        if (workerFree[i] > time) {
          nextTime = Math.min(nextTime, workerFree[i])
        }
      }
      if (nextTime === Infinity) break
      time = nextTime
      continue
    }

    // Sort ready by priority (descending) then name (ascending)
    ready.sort((a, b) => {
      const priorityDiff = priorities.get(b) - priorities.get(a)
      if (priorityDiff !== 0) return priorityDiff
      return a.localeCompare(b)
    })

    // Assign to free workers
    for (const name of ready) {
      // Find free worker with smallest index
      let freeWorker = -1
      let minTime = Infinity
      for (let i = 0; i < workers; i++) {
        if (workerFree[i] < minTime) {
          minTime = workerFree[i]
          freeWorker = i
        }
      }

      if (workerFree[freeWorker] > time) {
        // No worker is free at current time
        break
      }

      const start = Math.max(time, workerFree[freeWorker])
      const cost = tasks.get(name).cost
      const finish = start + cost

      workerTasks[freeWorker].push({ name, start, finish })
      finishes.set(name, finish)
      done.add(name)
      workerFree[freeWorker] = finish
    }

    if (done.size < tasks.size) {
      // Still have undone tasks but none are ready
      if (ready.length > 0 && done.size < tasks.size) {
        // Advance time
        let nextTime = Infinity
        for (let i = 0; i < workers; i++) {
          if (workerFree[i] > time) {
            nextTime = Math.min(nextTime, workerFree[i])
          }
        }
        if (nextTime !== Infinity) {
          time = nextTime
        } else {
          break
        }
      } else {
        break
      }
    }
  }

  // Calculate makespan
  let makespan = 0
  for (const finish of finishes.values()) {
    makespan = Math.max(makespan, finish)
  }

  return { workerTasks, makespan }
}

/**
 * Main function
 */
async function main() {
  const args = process.argv.slice(2)
  const argParse = parseArgs(args)
  if (argParse.error) {
    process.stderr.write(`error: ${argParse.error}\n`)
    process.exit(2)
  }

  const inputParse = await parseInput()
  if (inputParse.error) {
    process.stderr.write(inputParse.error + '\n')
    process.exit(2)
  }

  const { tasks, deps } = inputParse

  // Validate all referenced tasks exist
  const validateError = validateTasks(tasks, deps)
  if (validateError) {
    process.stderr.write(validateError.error + '\n')
    process.exit(2)
  }

  // Check for cycles
  const cycle = detectCycle(tasks, deps)
  if (cycle) {
    process.stderr.write(`error: cycle: ${cycle}\n`)
    process.exit(3)
  }

  const depths = calculateDepths(tasks, deps)
  const { starts, finishes } = calculateTiming(tasks, deps, depths)

  if (argParse.cmd === 'waves') {
    const waves = new Map()
    for (const [name, depth] of depths.entries()) {
      if (!waves.has(depth)) {
        waves.set(depth, [])
      }
      waves.get(depth).push(name)
    }

    // Sort wave numbers and print
    const sortedWaves = Array.from(waves.keys()).sort((a, b) => a - b)
    for (const wave of sortedWaves) {
      const names = waves.get(wave).sort()
      process.stdout.write(`wave ${wave}: ${names.join(' ')}\n`)
    }

    const maxFinish = Math.max(0, ...Array.from(finishes.values()))
    process.stdout.write(`total ${maxFinish}\n`)
  } else if (argParse.cmd === 'explain') {
    const names = Array.from(tasks.keys()).sort()
    for (const name of names) {
      const start = starts.get(name)
      const finish = finishes.get(name)
      const depth = depths.get(name)
      process.stdout.write(`${name} start=${start} finish=${finish} depth=${depth}\n`)
    }

    const maxFinish = Math.max(0, ...Array.from(finishes.values()))
    process.stdout.write(`total ${maxFinish}\n`)
  } else if (argParse.cmd === 'pack') {
    const { workerTasks, makespan } = pack(tasks, deps, argParse.workers)
    for (let i = 0; i < workerTasks.length; i++) {
      let line = `worker ${i}:`
      for (const task of workerTasks[i]) {
        line += ` ${task.name}@${task.start}-${task.finish}`
      }
      process.stdout.write(line + '\n')
    }
    process.stdout.write(`makespan ${makespan}\n`)
  }
}

main().catch(err => {
  process.stderr.write(`error: ${err.message}\n`)
  process.exit(2)
})

